 21	/**
 22	 * Encapsulates the reindex-specific interpretation of cancel-tasks responses and the response shaping needed for the cancel API.
 23	 */
 24	final class ReindexCancellation {
 25	
 26	    private ReindexCancellation() {}
 27	
 28	    /**
 29	     * Returns the real failure to surface from a cancel-tasks response, with any additional real failures attached as suppressed
 30	     * exceptions, or {@code null} when there are none. Validation-style node failures (handled separately by
 31	     * {@link #isNotFound(ListTasksResponse)}) are skipped.
 32	     */
 33	    static Exception cancellationFailure(final ListTasksResponse response) {
 34	        Exception head = null;
 35	        for (var nodeFailure : response.getNodeFailures()) {
 36	            if (isTaskValidationFailure(nodeFailure)) {
 37	                continue;
 38	            }
 39	            head = ExceptionsHelper.useOrSuppress(head, nodeFailure);
 40	        }
 41	        for (var taskFailure : response.getTaskFailures()) {
 42	            head = ExceptionsHelper.useOrSuppress(head, taskFailure.getCause());
 43	        }
 44	        return head;
 45	    }
 46	
 47	    /**
 48	     * Returns {@code true} when the cancel-tasks response indicates the target reindex task could not be located or did not qualify
 49	     * (non-reindex action, sub-task, non-cancellable). Such failures arrive as node failures whose cause is
 50	     * {@link ResourceNotFoundException} or {@link IllegalArgumentException} thrown by {@link TransportCancelTasksAction}.
 51	     * <p>
 52	     * We also require that no task failures are present, because a task failure signals a real cancel failure that must be surfaced
 53	     * to the caller.
 54	     */
 55	    static boolean isNotFound(final ListTasksResponse response) {
 56	        if (response.getTaskFailures().isEmpty() == false) {
 57	            return false;
 58	        }
 59	        if (response.getNodeFailures().isEmpty()) {
 60	            return false;
 61	        }
 62	        for (var failure : response.getNodeFailures()) {
 63	            if (isTaskValidationFailure(failure) == false) {
 64	                return false;
 65	            }
 66	        }
 67	        return true;
 68	    }
 69	
 70	    static ResourceNotFoundException notFoundException(final TaskId taskId) {
 71	        return new ResourceNotFoundException("reindex task [{}] either not found or completed", taskId);
 72	    }
 73	
 74	    /**
 75	     * Forces the completed task view to reflect cancellation, even if the stored task snapshot predates the cancellation flag update.
 76	     */
 77	    static CancelReindexResponse completedResponse(final GetReindexResponse getResponse) {
 78	        return new CancelReindexResponse(new GetReindexResponse(taskResultWithCancelledTrue(getResponse.getTaskResult())));
 79	    }
 80	
 81	    /**
 82	     * True iff the given node failure unwraps to one of the validation-style exceptions
 83	     * {@link TransportCancelTasksAction#processTasks} throws when the request targets a single task that doesn't qualify.
 84	     */
 85	    private static boolean isTaskValidationFailure(final ElasticsearchException failure) {
 86	        if (ExceptionsHelper.unwrap(failure, ResourceNotFoundException.class) != null) {
 87	            return true;
 88	        }
 89	        final IllegalArgumentException iae = (IllegalArgumentException) ExceptionsHelper.unwrap(failure, IllegalArgumentException.class);
 90	        if (iae == null) {
 91	            return false;
 92	        }
 93	        final String message = iae.getMessage();
 94	        return message != null && (message.contains("doesn't support this operation") || message.contains("doesn't support cancellation"));
 95	    }
 96	
 97	    private static TaskResult taskResultWithCancelledTrue(final TaskResult result) {
 98	        final TaskInfo taskInfo = result.getTask();
 99	        final TaskInfo newTaskInfo = new TaskInfo(
100	            taskInfo.taskId(),
101	            taskInfo.type(),
102	            taskInfo.node(),
103	            taskInfo.action(),
104	            taskInfo.description(),
105	            taskInfo.status(),
106	            taskInfo.startTime(),
107	            taskInfo.runningTimeNanos(),
108	            taskInfo.cancellable(),
109	            true,
110	            taskInfo.parentTaskId(),
111	            taskInfo.headers(),
112	            taskInfo.originalTaskId(),
113	            taskInfo.originalStartTimeMillis()
114	        );
115	        return new TaskResult(result.isCompleted(), newTaskInfo, result.getError(), result.getResponse());
116	    }
117	}

