 18	import org.elasticsearch.client.internal.Client;
 19	import org.elasticsearch.client.internal.OriginSettingClient;
 20	import org.elasticsearch.index.reindex.ReindexAction;
 21	import org.elasticsearch.injection.guice.Inject;
 22	import org.elasticsearch.logging.LogManager;
 23	import org.elasticsearch.logging.Logger;
 24	import org.elasticsearch.tasks.Task;
 25	import org.elasticsearch.tasks.TaskId;
 26	import org.elasticsearch.threadpool.ThreadPool;
 27	import org.elasticsearch.transport.TransportService;
 28	
 29	import java.util.Objects;
 30	
 31	import static org.elasticsearch.action.admin.cluster.node.tasks.get.TransportGetTaskAction.TASKS_ORIGIN;
 32	
 33	/** Transport action that cancels an in-flight reindex task and its descendants. */
 34	public class TransportCancelReindexAction extends HandledTransportAction<CancelReindexRequest, CancelReindexResponse> {
 35	
 36	    public static final ActionType<CancelReindexResponse> TYPE = new ActionType<>("cluster:admin/reindex/cancel");
 37	
 38	    private static final Logger logger = LogManager.getLogger(TransportCancelReindexAction.class);
 39	
 40	    private final Client client;
 41	
 42	    @Inject
 43	    public TransportCancelReindexAction(final TransportService transportService, final ActionFilters actionFilters, final Client client) {
 44	        super(
 45	            TYPE.name(),
 46	            transportService,
 47	            actionFilters,
 48	            CancelReindexRequest::new,
 49	            transportService.getThreadPool().executor(ThreadPool.Names.GENERIC)
 50	        );
 51	        this.client = new OriginSettingClient(Objects.requireNonNull(client), TASKS_ORIGIN);
 52	    }
 53	
 54	    @Override
 55	    protected void doExecute(
 56	        final Task thisTask,
 57	        final CancelReindexRequest request,
 58	        final ActionListener<CancelReindexResponse> listener
 59	    ) {
 60	        final TaskId taskId = request.getTaskId();
 61	
 62	        final CancelTasksRequest cancelTasksRequest = new CancelTasksRequest();
 63	        cancelTasksRequest.setTargetTaskId(taskId);
 64	        cancelTasksRequest.setActions(ReindexAction.NAME);
 65	        cancelTasksRequest.setExcludeChildTasks(true);
 66	        cancelTasksRequest.setWaitForCompletion(false);
 67	
 68	        client.execute(TransportCancelTasksAction.TYPE, cancelTasksRequest, listener.delegateFailureAndWrap((l, cancelResponse) -> {
 69	            // Maps validation and resource not found failures to reindex specific error
 70	            if (ReindexCancellation.isNotFound(cancelResponse)) {
 71	                logger.debug("cancel-tasks rejected task [{}]; reporting as reindex not found", taskId);
 72	                l.onFailure(ReindexCancellation.notFoundException(taskId));
 73	                return;
 74	            }
 75	            // Surface other failures as-is
 76	            final Exception cancelFailure = ReindexCancellation.cancellationFailure(cancelResponse);
 77	            if (cancelFailure != null) {
 78	                l.onFailure(cancelFailure);
 79	                return;
 80	            }
 81	            // No failure was reported but no task was matched either
 82	            if (cancelResponse.getTasks().isEmpty()) {
 83	                l.onFailure(ReindexCancellation.notFoundException(taskId));
 84	                return;
 85	            }
 86	
 87	            if (request.waitForCompletion()) {
 88	                // Fetch the completed reindex result with relocation following so the response reflects the original task identity.
 89	                final GetReindexRequest getRequest = new GetReindexRequest(taskId, true, null);
 90	                client.execute(
 91	                    TransportGetReindexAction.TYPE,
 92	                    getRequest,
 93	                    l.delegateFailureAndWrap(
 94	                        (l2, getResp) -> l2.onResponse(ReindexCancellation.completedResponse(getResp))
 95	                    )
 96	                );
 97	            } else {
 98	                l.onResponse(new CancelReindexResponse((GetReindexResponse) null));
 99	            }
100	        }));
101	    }
102	}
